import * as T from './vendor/three.module.js';
import {HOF} from './hof-layout.mjs';
import {pondSurfaceHeight} from './landscape-height.mjs';
// Organic pond inside the existing physical water boundary; no mirror render pass.
export function createHofPond(scene,height,animated,rockMaterial){
 const root=new T.Group();root.userData.kind='natural-hof-pond';scene.add(root);const {x,z,rx,rz}=HOF.pond,y=pondSurfaceHeight(),n=80,rings=12,positions=[x,y,z],colors=[],indices=[];const deep=new T.Color('#326f78'),edge=new T.Color('#799e88');colors.push(deep.r,deep.g,deep.b);
 const shore=a=>.91+.035*Math.sin(a*3+.7)+.025*Math.sin(a*7+1.2);
 for(let ring=1;ring<=rings;ring++)for(let j=0;j<n;j++){const a=j/n*Math.PI*2,r=ring/rings,s=shore(a);positions.push(x+Math.cos(a)*rx*r*s,y,z+Math.sin(a)*rz*r*s);const c=deep.clone().lerp(edge,Math.pow(r,3)*.85);colors.push(c.r,c.g,c.b);}
 for(let j=0;j<n;j++)indices.push(0,1+(j+1)%n,1+j);for(let ring=1;ring<rings;ring++)for(let j=0;j<n;j++){const a=1+(ring-1)*n+j,b=1+(ring-1)*n+(j+1)%n,c=a+n,d=b+n;indices.push(a,b,c,b,d,c);}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setAttribute('color',new T.Float32BufferAttribute(colors,3));geometry.setIndex(indices);geometry.computeVertexNormals();
 const time={value:0},material=new T.MeshStandardMaterial({vertexColors:true,roughness:.22,metalness:.08,transparent:true,opacity:.66,depthWrite:false});material.onBeforeCompile=shader=>{shader.uniforms.pondTime=time;shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 pondPoint;').replace('#include <begin_vertex>','#include <begin_vertex>\npondPoint=position;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 pondPoint;uniform float pondTime;').replace('#include <normal_fragment_maps>','#include <normal_fragment_maps>\nnormal=normalize(normal+vec3(sin(pondPoint.x*4.7+pondTime*.65)*.028,cos(pondPoint.z*3.6-pondTime*.5)*.022,0.0));').replace('#include <opaque_fragment>','float pondFresnel=pow(1.0-max(0.0,dot(normal,geometryViewDir)),3.0);outgoingLight=mix(outgoingLight,vec3(.61,.76,.80),pondFresnel*.35);\n#include <opaque_fragment>');};material.customProgramCacheKey=()=> 'hof-pond-soft-ripples-v1';const water=new T.Mesh(geometry,material);water.userData.kind='hof-pond-water';water.userData.shore='irregular';root.add(water);animated.push(t=>time.value=t);
 // Interrupted clusters, varied sizes and partly submerged stones replace the ring.
 for(let i=0;i<17;i++){const a=i*2.399;if(i%4===0)continue;const r=shore(a)+.025,s=.18+(i%5)*.055,o=new T.Mesh(new T.IcosahedronGeometry(1,2),rockMaterial);o.position.set(x+Math.cos(a)*rx*r,height(x+Math.cos(a)*rx*r,z+Math.sin(a)*rz*r)+s*.12,z+Math.sin(a)*rz*r);o.scale.set(s*(1.1+i%3*.15),s*.55,s);o.rotation.set(i*.3,i*.7,i*.13);root.add(o);}
 const pebbles=new T.InstancedMesh(new T.IcosahedronGeometry(1,1),rockMaterial,130),pebblePose=new T.Object3D();for(let i=0;i<130;i++){const a=i*2.399,r=.3+(i%17)/17*.68,px=x+Math.cos(a)*rx*r,pz=z+Math.sin(a)*rz*r,s=.045+(i%7)*.018;pebblePose.position.set(px,height(px,pz)+s*.3,pz);pebblePose.scale.set(s*1.4,s*.6,s);pebblePose.rotation.set(i,i*.7,0);pebblePose.updateMatrix();pebbles.setMatrixAt(i,pebblePose.matrix);}pebbles.userData.kind='pond-submerged-pebbles';root.add(pebbles);
 const reeds=new T.InstancedMesh(new T.CylinderGeometry(.012,.02,1,5),new T.MeshStandardMaterial({color:'#6e824b',roughness:1}),64),pose=new T.Object3D();for(let i=0;i<64;i++){const a=2.1+(i%16)*.023+(Math.floor(i/16)%2)*2.4,r=shore(a)+.045+(i%4)*.015,px=x+Math.cos(a)*rx*r,pz=z+Math.sin(a)*rz*r,h=.25+(i%7)*.07;pose.position.set(px,height(px,pz)+h/2,pz);pose.scale.set(1,h,1);pose.rotation.set(Math.sin(i)*.1,0,Math.cos(i)*.12);pose.updateMatrix();reeds.setMatrixAt(i,pose.matrix);}reeds.userData.kind='pond-bank-sedges';root.add(reeds);
 const fishMat=new T.MeshStandardMaterial({color:'#8c9980',roughness:.45}),fish=[];for(let i=0;i<7;i++){const g=new T.Group();g.userData.kind='living-pond-fish';g.userData.species=['trout','char','perch'][i%3];g.userData.size=.35+(i%4)*.24;g.scale.setScalar(.8+(i%4)*.18);const body=new T.Mesh(new T.SphereGeometry(1,12,8),fishMat);body.scale.set(.19,.045,.065);g.add(body);const tail=new T.Mesh(new T.ConeGeometry(.065,.12,3),fishMat);tail.rotation.z=Math.PI/2;tail.position.x=-.21;g.add(tail);const fin=new T.Mesh(new T.ConeGeometry(.045,.12,3),fishMat);fin.rotation.z=-.3;fin.position.set(0,.055,0);g.add(fin);for(const side of[-1,1]){const eye=new T.Mesh(new T.SphereGeometry(.012,6,5),new T.MeshBasicMaterial({color:'#192b28'}));eye.position.set(.13,.012,side*.047);g.add(eye);}root.add(g);const ring=new T.Mesh(new T.RingGeometry(.06,.075,28),new T.MeshBasicMaterial({color:'#d9e5ce',transparent:true,opacity:0,side:T.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;root.add(ring);animated.push(t=>{const a=t*(.1+i*.006)+i*.9,px=x+Math.cos(a)*rx*(.35+i*.045),pz=z+Math.sin(a*.8)*rz*.48;g.position.set(px,y-.13-Math.sin(i)*.025,pz);g.rotation.y=-Math.atan2(-Math.sin(a)*rx,Math.cos(a*.8)*rz*.8);tail.rotation.y=Math.sin(t*7+i)*.2;const phase=(t*.13+i*.31)%1;ring.position.set(px,y+.018,pz);ring.scale.setScalar(.6+phase*4);ring.material.opacity=phase<.35?(1-phase/.35)*.23:0;});fish.push(g);}
 let reflection=null;function captureReflection(renderer){if(reflection||!renderer.isWebGLRenderer)return;const needles=scene.children.find(o=>o.userData.kind==='needle-boughs');if(needles?.material.map&&!needles.material.map.image)return;reflection=new T.WebGLCubeRenderTarget(128,{generateMipmaps:true,minFilter:T.LinearMipmapLinearFilter});const camera=new T.CubeCamera(.3,480,reflection);camera.position.set(x,y+.5,z);camera.layers.set(2);camera.children.forEach(c=>c.layers.set(2));const allowed=new Set(['alpine-daylight-sky','authored-alpine-horizon','needle-boughs','golden-larch-boughs','swiss-chalet']);scene.traverse(o=>{if(o.isLight||allowed.has(o.userData.kind)||allowed.has(o.parent?.userData.kind))o.layers.enable(2);});try{water.visible=false;camera.update(renderer,scene);material.envMap=reflection.texture;material.envMapIntensity=.45;material.needsUpdate=true;}finally{water.visible=true;camera.removeFromParent();}}
 return{root,water,fish,captureReflection};
}
